class CV_EXPORTS Algorithm
{
public:
    Algorithm();
    virtual ~Algorithm();
    CV_WRAP virtual void clear() {}
    virtual void write(FileStorage& fs) const { CV_UNUSED(fs); }
    CV_WRAP void write(const Ptr<FileStorage>& fs, const String& name = String()) const;
    CV_WRAP virtual void read(const FileNode& fn) { CV_UNUSED(fn); }
    CV_WRAP virtual bool empty() const { return false; }
    template<typename _Tp> static Ptr<_Tp> read(const FileNode& fn) { Ptr<_Tp> obj = _Tp::create(); obj->read(fn); return !obj->empty() ? obj : Ptr<_Tp>(); }
    template<typename _Tp> static Ptr<_Tp> load(const String& filename, const String& objname=String()) { FileStorage fs(filename, FileStorage::READ); CV_Assert(fs.isOpened()); FileNode fn = objname.empty() ? fs.getFirstTopLevelNode() : fs[objname]; if (fn.empty()) return Ptr<_Tp>(); Ptr<_Tp> obj = _Tp::create(); obj->read(fn); return !obj->empty() ? obj : Ptr<_Tp>(); }
    template<typename _Tp> static Ptr<_Tp> loadFromString(const String& strModel, const String& objname=String()) { FileStorage fs(strModel, FileStorage::READ + FileStorage::MEMORY); FileNode fn = objname.empty() ? fs.getFirstTopLevelNode() : fs[objname]; Ptr<_Tp> obj = _Tp::create(); obj->read(fn); return !obj->empty() ? obj : Ptr<_Tp>(); }
    CV_WRAP virtual void save(const String& filename) const;
    CV_WRAP virtual String getDefaultName() const;
protected:
    void writeFormat(FileStorage& fs) const;
};

